def _in_scope(path: str, scope: dict) -> bool:
    prefixes = scope.get("pathPrefixes") or []
    excluded = scope.get("excludedPathPrefixes") or []
    for ex in excluded:
        if ex in (".", "") or _under(path, _internal_root(ex) if ex != "." else ""):
            if ex in (".", "") or path == _internal_root(ex) or path.startswith(_internal_root(ex).rstrip("/") + "/"):
                if ex not in (".", "") or True:
                    ir = "" if ex == "." else ex
                    if _under(path, ir) and ir != "":
